import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    cdc = inputs["cdc_events"]
    watermark = inputs["watermark"]

    high_ts = None
    if watermark is not None and len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]

    # Build initial state from target snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["item_id"]] = {
            "qty": float(row["qty_on_hand"]),
            "ts": row["last_event_ts"],
            "exists": True,
        }

    events = cdc.copy()
    if high_ts is not None and pd.notna(high_ts):
        events = events[events["event_ts"] > high_ts]

    events = events.sort_values(["event_ts", "event_seq"], kind="mergesort")

    for _, ev in events.iterrows():
        item = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        ts = ev["event_ts"]

        if item not in state:
            state[item] = {"qty": 0.0, "ts": None, "exists": False}

        s = state[item]

        if op == "R":
            if not s["exists"]:
                s["qty"] = 0.0
            s["qty"] = s["qty"] + qty
            s["exists"] = True
            s["ts"] = ts
        elif op == "A":
            s["qty"] = qty
            s["exists"] = True
            s["ts"] = ts
        elif op == "D":
            s["exists"] = False
            s["ts"] = ts

        state[item] = s

    rows = []
    for item, s in state.items():
        if s["exists"]:
            rows.append(
                {
                    "item_id": item,
                    "qty_on_hand": s["qty"],
                    "last_event_ts": s["ts"],
                }
            )

    new_snapshot = pd.DataFrame(rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    if len(new_snapshot) > 0:
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])
    else:
        new_snapshot = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": new_snapshot}
